import numpy as np

files = ['data/x.npy', 'data/logistic.npz', 'data/seq.npz', 'data/mlp.npz']

for f in files:
    print(f"--- Inspecting {f} ---")
    try:
        if f.endswith('.npy'):
            data = np.load(f)
            print(f"Shape: {data.shape}")
        else:
            data = np.load(f)
            print(f"Keys: {list(data.files)}")
            for k in data.files:
                print(f"  {k}: {data[k].shape}")
    except Exception as e:
        print(f"Error loading {f}: {e}")
EOF
